            .filter(|task| self.benchmark_campaign.selected_tasks.contains(task.id))
            .map(|task| task.id.to_owned())
            .collect(),
        repetitions: self.benchmark_campaign.repetitions,
        host_seed: self.benchmark_campaign.host_seed,
    })
}

